func lookupCJKGlyph(r rune) (int, bool) {
	if r > 0xffff {
		return 0, false
	}
	target := uint16(r)
	low := 0
	high := cjkGlyphCount - 1
	for low <= high {
		mid := low + (high-low)/2
		code := cjkGlyphCodeAt(mid)
		if code == target {
			return mid, true
		}
		if code < target {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	return 0, false
}

func cjkGlyphCodeAt(index int) uint16 {
	off := index * cjkCodeBytes
	return uint16(cjkGlyphCodes[off])<<8 | uint16(cjkGlyphCodes[off+1])
}

func cjkGlyphRow(index int, row int16) uint32 {
	off := index*cjkGlyphBytes + int(row)*cjkRowBytes
	return uint32(cjkGlyphData[off])<<16 | uint32(cjkGlyphData[off+1])<<8 | uint32(cjkGlyphData[off+2])
}
